const root = items[0].json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;
let url = String(body.url || body.source_url || '').trim();
if (!/^https?:\/\//i.test(url)) {
  throw new Error('Provide an http(s) url in body.url');
}
try {
  const u = new URL(url);
  const host = u.hostname.toLowerCase();
  if (host === 'localhost' || host.endsWith('.local') || host === '127.0.0.1' || host === '::1'
      || /^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[0-1])\.)/.test(host)) {
    throw new Error('Blocked private/local URL (SSRF protection)');
  }
} catch (e) {
  if (String(e.message).includes('Blocked')) throw e;
  throw new Error('Invalid URL');
}
const use_apify = body.use_apify === true || body.use_apify === 'true';
const deep_search = body.deep_search === true || body.deep_search === 'true';
return {
  source_url: url,
  use_apify,
  deep_search,
  search_query: body.search_query || '',
  max_results: Math.min(Number(body.max_results) || 3, 5)
};

const upstream = $('Normalize + Validate').first().json;
const crawlData = items[0].json;
const mainContent = Array.isArray(crawlData) ? (crawlData[0]?.text || '') : (crawlData.text || '');
return {
  source_url: upstream.source_url,
  raw_text: String(mainContent || 'No content found').slice(0, 50000),
  fetched_by: 'apify',
  ok: Boolean(mainContent)
};

const upstream = $('Normalize + Validate').first().json;
const resp = items[0].json;
let raw = '';
if (typeof resp === 'string') raw = resp;
else if (typeof resp.data === 'string') raw = resp.data;
else if (typeof resp.content === 'string') raw = resp.content;
else if (typeof resp.text === 'string') raw = resp.text;
else raw = JSON.stringify(resp);

raw = String(raw).replace(/\s+/g, ' ').trim();
const ok = raw.length >= 80 && !/just a moment|cf-browser-verification|access denied/i.test(raw);
return {
  source_url: upstream.source_url,
  raw_text: raw.slice(0, 50000),
  fetched_by: 'jina',
  ok,
  use_apify: upstream.use_apify,
  deep_search: upstream.deep_search,
  search_query: upstream.search_query,
  max_results: upstream.max_results
};

const upstream = $('Normalize + Validate').first().json;
const resp = items[0].json;
let html = '';
if (typeof resp === 'string') html = resp;
else if (typeof resp.data === 'string') html = resp.data;
else if (typeof resp.body === 'string') html = resp.body;
else html = String(resp.data || resp.text || '');

// crude readability: strip scripts/styles/tags
let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<nav[\s\S]*?<\/nav>/gi, ' ')
  .replace(/<footer[\s\S]*?<\/footer>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const ok = text.length >= 80;
return {
  source_url: upstream.source_url,
  raw_text: text.slice(0, 50000),
  fetched_by: 'http_html',
  ok,
  use_apify: upstream.use_apify
};

// Prefer successful path items; emit final contract for Logic Engine
const item = items[0].json;
if (!item.ok && !item.raw_text) {
  throw new Error('All fetchers failed to produce usable text');
}
return {
  raw_text: item.raw_text || '',
  source_url: item.source_url,
  fetched_by: item.fetched_by || 'unknown'
};
